import {inspectPacket,reviseOrder,reserveUnits,inspectEquipment,reconcileReceipt,qualifyOpportunity} from './models.mjs';

const WORDS={es:{navLab:'Demostraciones',navPartner:'Colaborar',eyebrow:'PRODUCTO · PROCESOS · AUTOMATIZACIÓN',title:'El trabajo avanza.<br>El contexto también.',intro:'Diseñamos productos que conectan la solicitud, la decisión y la entrega. Aquí puedes probar cómo se comportan cuando falta un dato, cambia un pedido o hace falta una aprobación.',explore:'Explorar los recorridos <span>↓</span>',partnerCta:'Construyamos con tu equipo ↗',heroNote:'Seis demostraciones funcionales. Todos los datos son ficticios.',boardLabel:'UNA ENTREGA, UN MISMO HILO',sample:'EJEMPLO FICTICIO / DEM-610',boardTitle:'Un cambio antes de producir',flow1:'La solicitud entra',flow1b:'Cantidad, referencia y versión juntas.',flow2:'El cambio queda visible',flow2b:'Lo nuevo se compara con lo aprobado.',flow3:'Una persona confirma',flow3b:'La siguiente etapa espera esa decisión.',human:'HUMANO',boardBottom:'La automatización prepara. El responsable decide.',strip1:'Entradas claras',strip2:'Reglas visibles',strip3:'Revisión humana',strip4:'Una salida comprobable',labEyebrow:'EL PORTAFOLIO, EN ACCIÓN',labTitle:'Prueba el momento<br>en que el trabajo cambia.',labIntro:'Elige un recorrido, cambia una condición y observa la decisión. Cada ejemplo muestra reglas reales ejecutándose en el navegador.',demoBadge:'DATOS FICTICIOS',measurement:'QUÉ COMPROBARÍAMOS EN UN PILOTO',reset:'Reiniciar ejemplo ↺',implementation:'Qué llevaría una implementación',impl1:'Entrada y responsable',impl1b:'Acordar de dónde llegan los datos, quién puede usarlos y qué considera completo el equipo.',impl2:'Reglas y excepciones',impl2b:'Probar faltantes, cambios, repetidos y fallos de conexión antes de ampliar el recorrido.',impl3:'Entrega y continuidad',impl3b:'Dejar criterios de aceptación, instrucciones, evidencias de prueba y una forma clara de retomar.',download:'Descargar ficha del ejemplo ↓',approachLabel:'CÓMO ATACAMOS UN PROBLEMA',approachTitle:'Una primera entrega<br>que pueda ponerse a prueba.',approach1:'Partimos del trabajo que ya hace el equipo. Identificamos el punto donde una solicitud necesita una decisión, un dato o una confirmación y construimos un primer tramo funcional.',approach2:'Cuando aporta, la IA ayuda a leer, clasificar o comparar. Sus resultados quedan sujetos a reglas y revisión. La integración con correo, hojas, CRM u otros sistemas se define con el acceso y las herramientas del cliente.',boundaryTitle:'Qué estás viendo aquí',boundaryBody:'Este portafolio reconstruye patrones de producto con modelos y datos nuevos. Las demostraciones no acceden a sistemas reales, no envían mensajes y no representan resultados económicos ni implantaciones de clientes. La revisión documental tampoco certifica cumplimiento legal.',collabLabel:'PARA EMPRESAS Y AGENCIAS',collabTitle:'Un equipo más<br>para construir contigo.',collabBody:'Podemos explorar un módulo acotado, una integración o un producto interno. Con tu equipo definimos alcance, revisión, entregables y continuidad para que la colaboración tenga un punto de partida concreto.',talkLabel:'CONVERSEMOS SOBRE ESE PRIMER TRAMO',emailCta:'Escribir por correo ↗',contactNote:'El ejemplo que elijas puede servir como punto de partida para la conversación.',footerNote:'Código independiente. Datos ficticios. Criterio visible.',source:'Ver el repositorio demo ↗'},en:{navLab:'Demonstrations',navPartner:'Work together',eyebrow:'PRODUCT · WORKFLOWS · AUTOMATION',title:'Work moves forward.<br>So does its context.',intro:'We design products that connect the request, the decision and the delivery. Try what happens when a detail is missing, an order changes or an approval is needed.',explore:'Explore the workflows <span>↓</span>',partnerCta:'Build with your team ↗',heroNote:'Six working demonstrations. Every record is fictional.',boardLabel:'ONE DELIVERY, A CONNECTED THREAD',sample:'FICTIONAL EXAMPLE / DEM-610',boardTitle:'A change before production',flow1:'The request comes in',flow1b:'Quantity, specification and version together.',flow2:'The change becomes visible',flow2b:'Compare the new request with the approved one.',flow3:'A person confirms',flow3b:'The next step waits for that decision.',human:'HUMAN',boardBottom:'Automation prepares. The owner decides.',strip1:'Clear inputs',strip2:'Visible rules',strip3:'Human review',strip4:'A verifiable output',labEyebrow:'THE PORTFOLIO, IN ACTION',labTitle:'Try the moment<br>when the work changes.',labIntro:'Choose a workflow, change a condition and see the decision. Each example runs actual rules in your browser.',demoBadge:'FICTIONAL DATA',measurement:'WHAT WE WOULD CHECK IN A PILOT',reset:'Reset example ↺',implementation:'What an implementation would include',impl1:'Input and ownership',impl1b:'Agree where data comes from, who may use it and what the team considers complete.',impl2:'Rules and exceptions',impl2b:'Test missing fields, changes, duplicate records and connection failures before expanding.',impl3:'Delivery and continuity',impl3b:'Leave acceptance criteria, operating notes, test evidence and a clear way to resume.',download:'Download the example brief ↓',approachLabel:'HOW WE APPROACH A PROBLEM',approachTitle:'A first delivery<br>you can put to the test.',approach1:'We start with the work your team already does. We find where a request needs a decision, a detail or a confirmation, and build a functional first section of that journey.',approach2:'Where useful, AI helps read, classify or compare. Its outputs remain subject to rules and review. Connections to email, spreadsheets, CRM or other systems depend on the access and tools agreed with the client.',boundaryTitle:'What you are seeing',boundaryBody:'This portfolio recreates product patterns with new models and fictional data. These demonstrations do not access real systems, send messages or establish client deployments or financial results. Document checks do not certify legal compliance.',collabLabel:'FOR BUSINESSES AND AGENCIES',collabTitle:'More hands<br>to build with your team.',collabBody:'We can explore a bounded module, an integration or an internal product. Together we define scope, review, deliverables and handover, giving the collaboration a concrete starting point.',talkLabel:'LET’S DISCUSS THAT FIRST SECTION',emailCta:'Write an email ↗',contactNote:'The example you choose can be the starting point for our conversation.',footerNote:'Independent code. Fictional data. Visible reasoning.',source:'Explore the demo repository ↗'}};

const CASES=[
{id:'packet',es:{name:'Documentos para revisar',sub:'De la recepción al expediente',kicker:'01 / CONSISTENCIA DOCUMENTAL',title:'El periodo del documento también importa.',story:'Un archivo llega a una solicitud de septiembre, pero corresponde a agosto. La revisión compara los datos y prepara lo que debe confirmar una persona.',measure:'Tiempo para armar un expediente, consultas por datos faltantes y correcciones del revisor.'},en:{name:'Documents for review',sub:'From intake to a review packet',kicker:'01 / DOCUMENT CONSISTENCY',title:'The document period matters too.',story:'A document arrives for a September request, but refers to August. The check compares the details and prepares what a person needs to confirm.',measure:'Time to assemble a packet, questions about missing information and reviewer corrections.'}},
{id:'order',es:{name:'Un pedido que cambia',sub:'De la versión a la aprobación',kicker:'02 / CAMBIOS Y APROBACIONES',title:'Lo solicitado y lo aprobado, a la vista.',story:'Un comprador ajusta la cantidad y el acabado. La nueva versión se compara con la base antes de preparar una instrucción para producción.',measure:'Confirmaciones necesarias ante un cambio y diferencias entre la versión aprobada y la entregada.'},en:{name:'An order that changes',sub:'From revision to approval',kicker:'02 / CHANGE AND APPROVAL',title:'See the request and the approval together.',story:'A buyer changes quantity and finish. The new version is compared with the baseline before a production instruction is prepared.',measure:'Confirmations needed for a change and differences between the approved and delivered versions.'}},
{id:'stock',es:{name:'Disponibilidad y reserva',sub:'De la consulta al compromiso',kicker:'03 / PEDIDOS E INVENTARIO',title:'Reservar sin prometer dos veces lo mismo.',story:'Hay 18 unidades y 7 ya están comprometidas. Prueba una reserva y vuelve a intentarla con la misma solicitud para ver cómo se evita duplicarla.',measure:'Reservas repetidas, diferencias de disponibilidad y pedidos que requieren confirmación adicional.'},en:{name:'Availability and reservation',sub:'From inquiry to commitment',kicker:'03 / ORDERS AND INVENTORY',title:'Reserve without promising the same stock twice.',story:'There are 18 units and 7 are committed. Try a reservation, then retry the same request to see how duplicate commitments are prevented.',measure:'Duplicate reservations, availability differences and orders requiring an additional confirmation.'}},
{id:'equipment',es:{name:'Servicio por equipo',sub:'De la entrada a los soportes',kicker:'04 / TRAZABILIDAD DE SERVICIO',title:'El equipo y su autorización siguen juntos.',story:'Una unidad entra para servicio con su identificación y anexos. El expediente muestra qué falta antes de pasarlo a revisión técnica.',measure:'Consultas para identificar equipos, anexos pendientes y correcciones al preparar la orden.'},en:{name:'Service by equipment',sub:'From intake to supporting records',kicker:'04 / SERVICE TRACEABILITY',title:'Keep the equipment and its approval together.',story:'A unit arrives for service with identification and attachments. Its packet shows what is missing before technical review.',measure:'Questions needed to identify equipment, missing attachments and service-order corrections.'}},
{id:'receipt',es:{name:'Un cobro por conciliar',sub:'Del movimiento a la revisión',kicker:'05 / CONCILIACIÓN ASISTIDA',title:'Un movimiento no cierra una conciliación.',story:'La referencia coincide, pero el valor recibido difiere del esperado. La revisión mantiene visible esa diferencia y la decisión del responsable.',measure:'Diferencias pendientes, tiempo de cotejo y decisiones que requieren evidencia adicional.'},en:{name:'A receipt to reconcile',sub:'From transaction to review',kicker:'05 / ASSISTED RECONCILIATION',title:'A transaction does not close a reconciliation.',story:'The reference matches, but the received amount differs from the expected one. The check keeps that difference and the reviewer’s decision visible.',measure:'Unresolved differences, comparison time and decisions requiring additional evidence.'}},
{id:'opportunity',es:{name:'Seguimiento con contexto',sub:'De la señal al próximo paso',kicker:'06 / OPERACIÓN COMERCIAL',title:'Una respuesta no es todavía un cierre.',story:'Una cuenta ficticia tiene evidencia, un canal y un historial. Cambia sus condiciones para distinguir un primer contacto, un acuse y una reunión.',measure:'Conversaciones con encaje, avance a reunión y propuesta, además de tiempo disponible para entregar.'},en:{name:'Follow-up with context',sub:'From signal to the next step',kicker:'06 / COMMERCIAL OPERATIONS',title:'A reply is not a closed deal yet.',story:'A fictional account has evidence, a channel and a history. Change those conditions to distinguish an initial contact, an acknowledgment and a meeting.',measure:'Qualified conversations, progress to meetings and proposals, and available delivery capacity.'}}
];
const INITIAL=[{expectedPeriod:'2026-09',documentPeriod:'2026-08',hasAttachment:true,approved:false},{baseline:{units:8,finish:'matte'},requested:{units:11,finish:'textured'},approved:false},{stock:18,committed:7,requested:4,existingReservation:false},{tagged:true,authorized:false,attachment:true},{expected:1860000,received:1810000,referenceMatches:true,reviewed:false},{sourceVerified:true,mailboxVerified:false,priorContact:false,suppressed:false,humanApproved:false,acknowledged:false,meetingConfirmed:false}];
let language='es', selected=0, scenarios=structuredClone(INITIAL), lastResult=null;
const $=s=>document.querySelector(s),choose=(es,en)=>language==='es'?es:en;
const fmt=n=>Number.isFinite(n)?new Intl.NumberFormat(language==='es'?'es-CO':'en-US').format(n):'—';
const check=(field,label,value)=>`<label class="check"><input type="checkbox" data-field="${field}" ${value?'checked':''}> <span>${label}</span></label>`;
const numeric=(field,label,value)=>`<label>${label}<input type="number" min="0" step="1" data-field="${field}" value="${Number.isFinite(value)?value:''}"></label>`;
const fact=(label,value)=>`<div class="fact"><span>${label}</span><strong>${value}</strong></div>`;
const notice=(tone,title,body)=>{const el=$('#demo-result');el.className=`result ${tone}`;el.hidden=false;el.innerHTML=`<strong>${title}</strong><span>${body}</span>`;};
const periodOptions=v=>['2026-08','2026-09'].map(x=>`<option value="${x}" ${v===x?'selected':''}>${x}</option>`).join('');
function workspace(){const s=scenarios[selected];let inside='',action='';
 if(selected===0){inside=`<div class="facts">${fact(choose('Expediente ficticio','Fictional packet'),'DEM-610')}${fact(choose('Periodo solicitado','Requested period'),s.expectedPeriod)}${fact(choose('Responsable','Owner'),choose('Revisor','Reviewer'))}</div><div class="fields"><label>${choose('Periodo del documento','Document period')}<select data-field="documentPeriod">${periodOptions(s.documentPeriod)}</select></label></div><div class="checks">${check('hasAttachment',choose('El anexo está disponible','The attachment is available'),s.hasAttachment)}${check('approved',choose('El revisor confirma el expediente','The reviewer confirms the packet'),s.approved)}</div>`;action=choose('Revisar consistencia','Check consistency');}
 if(selected===1){inside=`<div class="facts">${fact(choose('Versión base','Baseline'),choose('8 unidades','8 units'))}${fact(choose('Acabado base','Baseline finish'),choose('Mate','Matte'))}${fact(choose('Versión solicitada','Requested revision'),'02')}</div><div class="fields">${numeric('units',choose('Nueva cantidad','New quantity'),s.requested.units)}<label>${choose('Nuevo acabado','New finish')}<select data-field="finish"><option value="matte" ${s.requested.finish==='matte'?'selected':''}>${choose('Mate','Matte')}</option><option value="textured" ${s.requested.finish==='textured'?'selected':''}>${choose('Texturado','Textured')}</option></select></label></div><div class="checks">${check('approved',choose('El responsable aprueba esta versión completa','The owner approves this complete revision'),s.approved)}</div>`;action=choose('Comparar y preparar','Compare and prepare');}
 if(selected===2){inside=`<div class="facts">${fact(choose('Existencias','Stock'),fmt(s.stock))}${fact(choose('Comprometidas','Committed'),fmt(s.committed))}${fact(choose('Disponibles','Available'),fmt(s.stock-s.committed))}</div><div class="fields">${numeric('requested',choose('Unidades para DEM-623','Units for DEM-623'),s.requested)}</div><p class="quiet">${choose('El mismo identificador se conserva al repetir la reserva. Reinicia para probar una solicitud nueva.','The same request identifier is kept on a retry. Reset to try a new request.')}</p>`;action=choose('Probar reserva','Test reservation');}
 if(selected===3){inside=`<div class="facts">${fact(choose('Unidad ficticia','Fictional unit'),'EQ-DEMO-04')}${fact(choose('Recorrido','Workflow'),choose('Servicio','Service'))}${fact(choose('Decisión final','Final decision'),choose('Revisión técnica','Technical review'))}</div><div class="checks">${check('tagged',choose('Identificación de la unidad confirmada','Unit identification confirmed'),s.tagged)}${check('authorized',choose('Alcance autorizado por el responsable','Scope authorized by the owner'),s.authorized)}${check('attachment',choose('Anexo asociado a esta unidad','Attachment linked to this unit'),s.attachment)}</div>`;action=choose('Preparar el ingreso','Prepare intake');}
 if(selected===4){inside=`<div class="facts">${fact(choose('Esperado ficticio (COP)','Fictional expected amount (COP)'),fmt(s.expected))}${fact(choose('Referencia','Reference'),'REF-DEMO-82')}${fact(choose('Ganancia registrada','Profit recorded'),choose('No se calcula','Not calculated'))}</div><div class="fields">${numeric('received',choose('Valor recibido ficticio (COP)','Fictional amount received (COP)'),s.received)}</div><div class="checks">${check('referenceMatches',choose('La referencia corresponde a la solicitud','The reference matches the request'),s.referenceMatches)}${check('reviewed',choose('El responsable revisó los soportes','The owner reviewed the supporting records'),s.reviewed)}</div>`;action=choose('Cotejar el movimiento','Compare the transaction');}
 if(selected===5){inside=`<div class="checks">${check('sourceVerified',choose('Fuente comercial comprobada','Business source checked'),s.sourceVerified)}${check('mailboxVerified',choose('Buzón verificado por un proveedor','Mailbox verified by a provider'),s.mailboxVerified)}${check('priorContact',choose('Existe contacto previo','There is previous contact'),s.priorContact)}${check('suppressed',choose('La cuenta pidió no recibir mensajes','The account asked not to be contacted'),s.suppressed)}${check('humanApproved',choose('La persona responsable aprobó el acercamiento','The owner approved the approach'),s.humanApproved)}${check('acknowledged',choose('La cuenta confirmó recepción','The account acknowledged receipt'),s.acknowledged)}${check('meetingConfirmed',choose('La cuenta confirmó una reunión','The account confirmed a meeting'),s.meetingConfirmed)}</div>`;action=choose('Resolver próximo paso','Determine the next step');}
 $('#demo-workspace').innerHTML=`<div class="workbench"><div class="workbench-head"><span>${choose('ESCENARIO LOCAL / SIN CONEXIONES EXTERNAS','LOCAL SCENARIO / NO EXTERNAL CONNECTIONS')}</span><span>↗ ${String(selected+1).padStart(2,'0')}</span></div><div class="bench-body">${inside}<div class="bench-action"><button id="run-demo" class="button dark">${action} <span>→</span></button><p class="quiet">${choose('La acción afecta sólo este ejemplo.','This action affects only this example.')}</p></div><div id="demo-result" class="result" role="status" aria-live="polite" hidden></div></div></div>`;
 $('#demo-workspace').querySelectorAll('[data-field]').forEach(el=>el.addEventListener('input',()=>{const key=el.dataset.field,v=el.type==='checkbox'?el.checked:el.type==='number'?(el.value.trim()===''?NaN:Number(el.value)):el.value;if(selected===1&&key==='units')s.requested.units=v;else if(selected===1&&key==='finish')s.requested.finish=v;else s[key]=v;lastResult=null;$('#demo-result').hidden=true;}));
 $('#run-demo').addEventListener('click',run);
}
function run(){const s=scenarios[selected];let r;
 if(selected===0){r=inspectPacket(s);const consistent=s.documentPeriod===s.expectedPeriod&&s.hasAttachment;if(!consistent)notice('pending',choose('El expediente requiere una revisión','The packet needs review'),choose('Comprueba el periodo y la presencia del anexo. Una confirmación no elimina una diferencia de datos.','Check the period and attachment. A confirmation does not remove a data mismatch.'));else if(!s.approved)notice('pending',choose('Datos consistentes, decisión pendiente','Consistent data, decision pending'),choose('La información está preparada. Falta la confirmación del revisor.','The information is prepared. The reviewer still needs to confirm.'));else notice('good',choose('Expediente preparado para continuar','Packet prepared to continue'),choose('Periodo, anexo y confirmación coinciden. Esta comprobación no certifica cumplimiento legal.','Period, attachment and confirmation agree. This check does not certify legal compliance.'));}
 if(selected===1){r=reviseOrder(s);const changes=r.changes??[];if(!Number.isSafeInteger(s.requested.units)||s.requested.units<=0)notice('bad',choose('Revisa la cantidad','Check the quantity'),choose('Usa un entero positivo para comparar la versión.','Use a positive integer to compare the revision.'));else notice(r.productionAllowed?'good':'pending',r.productionAllowed?choose('Versión aprobada para preparar la instrucción','Approved revision ready for instruction'):choose('Comparación preparada, aprobación pendiente','Comparison prepared, approval pending'),choose(`${changes.length} cambios identificados. La cantidad solicitada es ${fmt(s.requested.units)} y el acabado ${s.requested.finish==='matte'?'mate':'texturado'}. La aprobación se aplica a esta versión.`,`${changes.length} changes identified. The requested quantity is ${fmt(s.requested.units)} and the finish is ${s.requested.finish}. Approval applies to this revision.`));}
 if(selected===2){r=reserveUnits(s);if(!r.ok)notice('bad',choose('La reserva no puede continuar','The reservation cannot proceed'),choose('La cantidad debe ser un entero positivo y caber en las existencias disponibles. No se descontaron unidades.','Quantity must be a positive integer within available stock. No units were deducted.'));else if(s.existingReservation)notice('pending',choose('Solicitud ya reservada','Request already reserved'),choose('Repetir DEM-623 no vuelve a descontar unidades. Reinicia para ensayar una solicitud diferente.','Retrying DEM-623 does not deduct units again. Reset to test a different request.'));else {s.existingReservation=true;s.committed+=r.reservedNow;workspace();notice('good',choose('Reserva simulada registrada','Simulated reservation recorded'),choose(`${fmt(r.reservedNow)} unidades reservadas. Quedan ${fmt(r.availableAfter)} disponibles. Repite el botón para comprobar el control de duplicados.`,`${fmt(r.reservedNow)} units reserved. ${fmt(r.availableAfter)} remain available. Retry the button to check duplicate protection.`));}}
 if(selected===3){r=inspectEquipment(s);notice(r.ok?'good':'pending',r.ok?choose('El ingreso está preparado','Intake is prepared'):choose('Faltan confirmaciones del ingreso','Intake confirmations are missing'),r.ok?choose('Identificación, alcance y anexo están presentes. El criterio técnico permanece a cargo del equipo responsable.','Identification, scope and attachment are present. Technical judgment remains with the responsible team.'):choose('Revisa la identificación, la autorización y el anexo de esta unidad antes de pasarla a la siguiente etapa.','Review identification, authorization and this unit’s attachment before moving it to the next step.'));}
 if(selected===4){r=reconcileReceipt(s);const valid=Number.isSafeInteger(s.received)&&s.received>=0;if(!valid)notice('bad',choose('Revisa el importe','Check the amount'),choose('El ejemplo requiere un importe entero no negativo.','The example requires a nonnegative integer amount.'));else if(r.difference!==0||!s.referenceMatches)notice('pending',choose('Hay una diferencia por resolver','A difference needs resolution'),choose(`Diferencia recibida frente a lo esperado: ${fmt(r.difference)} COP. Confirma referencia y soportes antes de conciliar. No se registra ganancia.`,`Received minus expected: ${fmt(r.difference)} COP. Confirm reference and records before reconciliation. No profit is recorded.`));else if(!s.reviewed)notice('pending',choose('Los datos coinciden, falta revisión','The data matches; review is pending'),choose('El responsable debe revisar los soportes. La coincidencia de valores prepara esa decisión.','The owner needs to review the supporting records. Matching values prepares that decision.'));else notice('good',choose('Cotejo consistente y revisado','Consistent comparison, reviewed'),choose('La referencia y el valor coinciden y el responsable revisó los soportes. El ejemplo no convierte un cobro en ganancia.','Reference and amount match, and the owner reviewed the records. The example does not turn a receipt into profit.'));}
 if(selected===5){r=qualifyOpportunity(s);if(s.suppressed)notice('bad',choose('No contactar','Do not contact'),choose('La oposición conserva prioridad aunque exista un buzón verificado. No se prepara un nuevo primer acercamiento.','The opt-out takes priority even with a verified mailbox. A new initial approach is not prepared.'));else if(s.meetingConfirmed)notice('good',choose('Reunión confirmada, alcance por conocer','Meeting confirmed; scope still to establish'),choose('El siguiente paso es preparar contexto y preguntas. Una reunión aún no es una propuesta aceptada ni una venta.','Prepare context and questions next. A meeting is not an accepted proposal or a sale.'));else if(s.acknowledged)notice('pending',choose('Recepción confirmada','Receipt acknowledged'),choose('Conserva la respuesta y define un próximo paso pertinente. El acuse no confirma necesidad, presupuesto o cierre.','Keep the reply and define a relevant next step. An acknowledgment does not confirm need, budget or a deal.'));else if(s.priorContact)notice('pending',choose('Revisar el historial antes de actuar','Review history before acting'),choose('Un primer contacto ya registrado no se repite por haber pasado una verificación.','A recorded first approach is not repeated just because verification passed.'));else if(r.allowed)notice('good',choose('Controles del ejemplo superados','Example checks passed'),choose('Fuente, buzón, historial y aprobación permiten preparar el acercamiento ficticio. Esta demostración no envía mensajes.','Source, mailbox, history and approval allow preparing the fictional approach. This demonstration sends no messages.'));else notice('pending',choose('Faltan controles para continuar','Checks are still missing'),choose('Comprueba la fuente, el buzón y la aprobación humana. No se da por enviado lo que sigue en revisión.','Check the source, mailbox and human approval. An item under review is not marked as sent.'));}
 lastResult=structuredClone(r);updateContacts();
}
function updateContacts(){const c=CASES[selected][language],body=choose(`Hola, Jair. Me interesa explorar una colaboración a partir del ejemplo «${c.name}». El recorrido que queremos trabajar es…`,`Hi Jair. I would like to explore a collaboration based on the “${c.name}” example. The workflow we want to work on is…`);$('#email-contact').href='mailto:automatizaciones.storres@gmail.com?'+new URLSearchParams({subject:choose('Una primera conversación sobre automatización','An initial conversation about automation'),body});$('#whatsapp-contact').href='https://wa.me/573105497003?'+new URLSearchParams({text:body});}
function render(){document.documentElement.lang=language;document.title=choose('Automatizaciones Torres · Productos que conectan el trabajo','Automatizaciones Torres · Products that connect the work');document.querySelectorAll('[data-i18n]').forEach(el=>{el.innerHTML=WORDS[language][el.dataset.i18n]??el.dataset.i18n;});$('#language').textContent=language==='es'?'EN ↗':'ES ↗';$('#language').setAttribute('aria-label',choose('Switch to English','Cambiar a español'));$('#case-tabs').setAttribute('aria-label',choose('Demostraciones','Demonstrations'));$('#case-tabs').innerHTML=CASES.map((c,i)=>`<button id="case-tab-${i}" role="tab" aria-selected="${i===selected}" aria-controls="case-panel" tabindex="${i===selected?0:-1}" data-case="${i}"><span class="case-index">${String(i+1).padStart(2,'0')}</span><span><strong>${c[language].name}</strong><small>${c[language].sub}</small></span></button>`).join('');$('#case-tabs').querySelectorAll('[data-case]').forEach(el=>{el.addEventListener('click',()=>selectCase(Number(el.dataset.case)));el.addEventListener('keydown',e=>{let i=selected;if(e.key==='ArrowDown'||e.key==='ArrowRight')i=(i+1)%CASES.length;else if(e.key==='ArrowUp'||e.key==='ArrowLeft')i=(i+CASES.length-1)%CASES.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=CASES.length-1;else return;e.preventDefault();selectCase(i);$(`#case-tab-${i}`).focus();});});const c=CASES[selected][language];$('#case-panel').setAttribute('aria-labelledby',`case-tab-${selected}`);$('#case-kicker').textContent=c.kicker;$('#case-title').textContent=c.title;$('#case-story').textContent=c.story;$('#case-measure').textContent=c.measure;workspace();updateContacts();}
function selectCase(i){selected=i;lastResult=null;render();}
$('#language').addEventListener('click',()=>{language=language==='es'?'en':'es';lastResult=null;render();});$('#reset').addEventListener('click',()=>{scenarios[selected]=structuredClone(INITIAL[selected]);lastResult=null;render();});$('#download').addEventListener('click',()=>{const c=CASES[selected][language],text=[`Automatizaciones Torres — ${c.name}`,'',choose('DEMOSTRACIÓN CON DATOS FICTICIOS','DEMONSTRATION WITH FICTIONAL DATA'),'',c.story,'',WORDS[language].measurement,c.measure,'',choose('El alcance real se define con el equipo, sus herramientas, datos autorizados y criterio de aceptación.','Actual scope is defined with the team, their tools, authorized data and acceptance criteria.'),'',JSON.stringify({fictional:true,scenario:CASES[selected].id,input:scenarios[selected],result:lastResult},null,2),'','Jair Peinado · Automatizaciones Torres','automatizaciones.storres@gmail.com'].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`torres-demo-${CASES[selected].id}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);});render();
